package com.stylemind.commerce.entity;
import jakarta.persistence.Column; import jakarta.persistence.Entity; import jakarta.persistence.Id; import jakarta.persistence.Table; import java.time.OffsetDateTime; import java.util.UUID; import lombok.Getter; import lombok.NoArgsConstructor; import lombok.Setter;
@Entity @Table(name="cancellation_request",schema="public") @Getter @Setter @NoArgsConstructor
public class CancellationRequest { @Id @Column(name="cancellation_request_id") private UUID cancellationRequestId; @Column(name="order_id",nullable=false,unique=true) private UUID orderId; @Column(name="requested_by_user_id",nullable=false) private UUID requestedByUserId; @Column(nullable=false) private String reason; @Column(name="request_status",nullable=false) private String requestStatus; @Column(name="requested_at",nullable=false) private OffsetDateTime requestedAt; @Column(name="reviewed_by_user_id") private UUID reviewedByUserId; @Column(name="reviewed_at") private OffsetDateTime reviewedAt; @Column(name="decision_reason") private String decisionReason; }
